static inline double panasonic_soc_proxy_rf_50_trees_predict(const float features[PANASONIC_SOC_PROXY_RF_50_TREES_FEATURE_COUNT])
{
    if (features == 0) {
        return NAN;
    }
    for (int32_t feature_index = 0;
         feature_index < PANASONIC_SOC_PROXY_RF_50_TREES_FEATURE_COUNT;
         ++feature_index) {
        if (!isfinite((double)features[feature_index])) {
            return NAN;
        }
    }

    double prediction_sum = 0.0;
    for (uint32_t tree_index = 0;
         tree_index < PANASONIC_SOC_PROXY_RF_50_TREES_TREE_COUNT;
         ++tree_index) {
        const uint32_t tree_start = panasonic_soc_proxy_rf_50_trees_tree_offsets[tree_index];
        const uint32_t tree_end = panasonic_soc_proxy_rf_50_trees_tree_offsets[tree_index + 1];
        uint32_t node_index = 0;
        uint32_t steps = 0;

        while (tree_start + node_index < tree_end && steps++ < tree_end - tree_start) {
            const uint32_t flat_index = tree_start + node_index;
            const int8_t feature_index =
                panasonic_soc_proxy_rf_50_trees_node_features[flat_index];
            if (feature_index < 0) {
                prediction_sum += panasonic_soc_proxy_rf_50_trees_leaf_values[flat_index];
                break;
            }
            if (features[feature_index] <=
                panasonic_soc_proxy_rf_50_trees_thresholds[flat_index]) {
                node_index = (uint32_t)
                    panasonic_soc_proxy_rf_50_trees_left_children[flat_index];
            } else {
                node_index = (uint32_t)
                    panasonic_soc_proxy_rf_50_trees_right_children[flat_index];
            }
        }
        if (tree_start + node_index >= tree_end || steps > tree_end - tree_start) {
            return NAN;
        }
    }
    return prediction_sum / PANASONIC_SOC_PROXY_RF_50_TREES_TREE_COUNT;
}

